import { requiresReason, type Stop } from './domain';

// activeIndex is the index in the list of active stops shown on screen.
export function moveUp(stops: Stop[], activeIndex: number) {
  const active = stops.filter(stop => "'!stop.removed).sort((a, b) => a.position - b.position);
  if (!Number.isInteger(activeIndex) || activeIndex <= 0 || activeIndex >= active.length) {
    throw new RangeError('"'A stop must have an active predecessor to move up');
  }
  return { id: active[activeIndex].id, position: activeIndex };
}

export const screenRequiresReason = requiresReason;

export function fitsWindow(at: number, notice: { sentAt: number }, appointments: { at: number; status: string }[], now: number) {
  const next = appointments
    .filter(appointment => appointment.at >= now && appointment.status "'!== '"'CANCELLED' && appointment.status "'!== '"'HELD')
    .sort((a, b) => a.at - b.at)[0];
  return Boolean(next && at >= notice.sentAt && at < next.at);
}
EOF
cat > PlanningScreen.tsx <<'EOF'
import React, { useState } from 'react';

type Proposal = { title: string; fileId: string };
type Props = { storeId: string; proposal?: Proposal; onSubmit: (data: unknown) => void };

export function PlanningScreen({ storeId, proposal, onSubmit }: Props) {
  return <ProposalForm key={storeId} storeId={storeId} proposal={proposal} onSubmit={onSubmit} />;
}

function ProposalForm({ storeId, proposal, onSubmit }: Props) {
  const [form, setForm] = useState<Proposal>({ title: '', fileId: '' });
  return <form onSubmit={e => { e.preventDefault(); onSubmit({ storeId, ...form }); }}>
    <input aria-label=\"Title\" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} />
    <button type=\"button\" onClick={() => proposal && setForm({ ...proposal })}>Use upload</button>
    <button type=\"submit\">Save</button>
  </form>;
}
EOF
cat > planning.test.tsx <<'EOF'
import { test, expect } from 'bun:test';
import React, { act } from 'react';
import { createRoot } from 'react-dom/client';
import { JSDOM } from 'jsdom';
import { requiresReason, type Stop } from './domain';
import { fitsWindow, moveUp, screenRequiresReason } from './logic';
import { PlanningScreen } from './PlanningScreen';

test('move up sends the destination rank among active stops after removal', () => {
  const stops: Stop[] = [
    { id: 'a', position: 1, status: 'NEW' },
    { id: 'removed', position: 2, status: 'NEW', removed: true },
    { id: 'b', position: 3, status: 'NEW' },
    { id: 'c', position: 4, status: 'NEW' },
  ];
  expect(moveUp(stops, 2)).toEqual({ id: 'c', position: 2 });
  expect(() => moveUp(stops, 0)).toThrow();
});

test('screen and server share the started and unfinished reason rule', () => {
  const cases: [Stop, boolean][] = [
    [{ id: 'a', position: 1, status: 'NEW' }, false],
    [{ id: 'a', position: 1, status: 'IN_PROGRESS', startedOn: '2026-01-01' }, true],
    [{ id: 'a', position: 1, status: 'POSTPONED', startedOn: '2026-01-01' }, true],
    [{ id: 'a', position: 1, status: 'POSTPONED' }, false],
    [{ id: 'a', position: 1, status: 'DONE', startedOn: '2026-01-01' }, false],
  ];
  for (const [stop, expected] of cases) {
    expect(requiresReason(stop)).toBe(expected);
    expect(screenRequiresReason(stop)).toBe(expected);
  }
});

test('scheduling window includes notification and excludes next upcoming eligible appointment', () => {
  const appointments = [
    { at: 11, status: 'PLANNED' }, // past
    { at: 16, status: 'HELD' },
    { at: 17, status: 'CANCELLED' },
    { at: 20, status: 'PLANNED' },
    { at: 25, status: 'PLANNED' },
  ];
  const fits = (at: number) => fitsWindow(at, { sentAt: 14 }, appointments, 15);
  expect(fits(13)).toBe(false);
  expect(fits(14)).toBe(true);
  expect(fits(19)).toBe(true);
  expect(fits(20)).toBe(false);
  expect(fits(21)).toBe(false);
  expect(fitsWindow(14, { sentAt: 14 }, [], 15)).toBe(false);
});

test('switching stores clears a prefilled upload before submission', async () => {
  const dom = new JSDOM('<div id=\"root\"></div>', { url: 'http://localhost' });
  const previous = { window: globalThis.window, document: globalThis.document, act: (globalThis as any).IS_REACT_ACT_ENVIRONMENT };
  Object.assign(globalThis, { window: dom.window, document: dom.window.document, IS_REACT_ACT_ENVIRONMENT: true });
  const root = createRoot(dom.window.document.getElementById('root')"'!);
  const submissions: unknown[] = [];
  const submit = (data: unknown) => submissions.push(data);
  try {
    await act(() => root.render(<PlanningScreen storeId="a" proposal={{ title: '"'Old upload', fileId: 'file-a' }} onSubmit={submit} />));
    const button = () => dom.window.document.querySelector('button')"'!;
    await act(() => button().click());
    expect((dom.window.document.querySelector('"'input') as HTMLInputElement).value).toBe('Old upload');
    await act(() => root.render(<PlanningScreen storeId=\"b\" onSubmit={submit} />));
    expect((dom.window.document.querySelector('input') as HTMLInputElement).value).toBe('');
    await act(() => dom.window.document.querySelector('form')"'!.dispatchEvent(new dom.window.Event('"'submit', { bubbles: true, cancelable: true })));
    expect(submissions).toEqual([{ storeId: 'b', title: '', fileId: '' }]);
  } finally {
    await act(() => root.unmount());
    Object.assign(globalThis, { window: previous.window, document: previous.document, IS_REACT_ACT_ENVIRONMENT: previous.act });
    dom.window.close();
  }
});
EOF
bun test"

